let aiContent = '';
try {
  aiContent = $input.first().json.choices[0].message.content || '';
  // Nettoyer les blocs markdown si l'IA en a ajouté
  aiContent = aiContent.replace(/^```html\s*/i, '').replace(/```\s*$/i, '').trim();
} catch(e) {
  aiContent = '<p>Content unavailable — please contact AutoFlow AI directly.</p>';
}

let client = {};
try { client = $('Extraire données Tally').first().json; } catch(e) {
  client = { nom: 'Client', email: '', site: '', plateforme: '', ca: '', probleme: '', objectif: '', budget: '', urgence: '', langue: 'fr' };
}

const lang = client.langue || 'fr';
const isEN = lang === 'en';

const date = new Date().toLocaleDateString(isEN ? 'en-GB' : 'fr-FR', {
  day: '2-digit', month: 'long', year: 'numeric'
});

const labels = isEN ? {
  title: 'E-Commerce Automation Audit',
  subtitle: 'Personalised Report — Confidential',
  clientLabel: 'Client', siteLabel: 'Website',
  platformLabel: 'Platform', revenueLabel: 'Monthly Revenue',
  budgetLabel: 'Planned Budget', dateLabel: 'Date',
  footerTag: '⚡ AutoFlow AI', footerSub: 'n8n & AI Automation Expert for E-commerce'
} : {
  title: "Audit d'Automatisation E-commerce",
  subtitle: 'Rapport personnalisé — Confidentiel',
  clientLabel: 'Client', siteLabel: 'Site',
  platformLabel: 'Plateforme', revenueLabel: 'CA mensuel',
  budgetLabel: 'Budget prévu', dateLabel: 'Date',
  footerTag: '⚡ AutoFlow AI', footerSub: 'Expert n8n & Automatisation IA pour E-commerçants'
};

const html = `<!DOCTYPE html>
<html lang="${lang}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${labels.title} — ${client.nom}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&family=Outfit:wght@800;900&display=swap');
  * { margin:0; padding:0; box-sizing:border-box; }
  body { font-family:'Inter',Arial,sans-serif; background:#fff; color:#111827; font-size:14px; line-height:1.6; }
  .header { background:linear-gradient(135deg,#7c3aed,#3b82f6); color:#fff; padding:40px 48px; }
  .header-logo { font-family:'Outfit',Arial Black,sans-serif; font-size:1rem; font-weight:900; letter-spacing:-0.02em; opacity:0.9; margin-bottom:20px; }
  .header h1 { font-family:'Outfit',Arial Black,sans-serif; font-size:2rem; font-weight:900; line-height:1.1; margin-bottom:6px; }
  .header p { opacity:0.85; font-size:0.9rem; }
  .meta-grid { display:grid; grid-template-columns:1fr 1fr 1fr; gap:0; border-bottom:2px solid #e5e7eb; }
  .meta-item { padding:18px 24px; border-right:1px solid #e5e7eb; }
  .meta-item:last-child { border-right:none; }
  .meta-item label { display:block; font-size:0.65rem; font-weight:700; text-transform:uppercase; letter-spacing:0.08em; color:#6b7280; margin-bottom:4px; }
  .meta-item span { font-size:0.88rem; color:#111827; font-weight:600; }
  .content { padding:40px 48px; }
  .content h2 { font-family:'Outfit',Arial Black,sans-serif; font-size:1.25rem; font-weight:900; color:#7c3aed; border-left:4px solid #7c3aed; padding-left:14px; margin:36px 0 14px; }
  .content h2:first-child { margin-top:0; }
  .content h3 { font-size:0.95rem; font-weight:700; color:#1e1b4b; margin:18px 0 8px; }
  .content p { color:#374151; line-height:1.75; margin-bottom:12px; font-size:0.88rem; }
  .content ul, .content ol { padding-left:20px; margin-bottom:12px; }
  .content li { color:#374151; line-height:1.7; margin-bottom:4px; font-size:0.88rem; }
  .content strong { color:#111827; }
  .footer { margin-top:48px; padding:20px 48px; background:linear-gradient(135deg,rgba(124,58,237,0.06),rgba(59,130,246,0.06)); border-top:2px solid #7c3aed; display:flex; justify-content:space-between; align-items:center; }
  .footer-brand { font-family:'Outfit',Arial Black,sans-serif; font-weight:900; font-size:0.9rem; color:#7c3aed; }
  .footer small { color:#6b7280; font-size:0.75rem; }
</style>
</head>
<body>
<div class="header">
  <div class="header-logo">⚡ AutoFlow AI</div>
  <h1>${labels.title}</h1>
  <p>${labels.subtitle}</p>
</div>
<div class="meta-grid">
  <div class="meta-item"><label>${labels.clientLabel}</label><span>${client.nom}</span></div>
  <div class="meta-item"><label>${labels.siteLabel}</label><span>${client.site}</span></div>
  <div class="meta-item"><label>${labels.platformLabel}</label><span>${client.plateforme}</span></div>
  <div class="meta-item"><label>${labels.revenueLabel}</label><span>${client.ca}</span></div>
  <div class="meta-item"><label>${labels.budgetLabel}</label><span>${client.budget}</span></div>
  <div class="meta-item"><label>${labels.dateLabel}</label><span>${date}</span></div>
</div>
<div class="content">
${aiContent}
</div>
<div class="footer">
  <div class="footer-brand">${labels.footerTag}</div>
  <small>${labels.footerSub}</small>
</div>
</body>
</html>`;

return [{ json: { html, nom: client.nom, email: client.email, site: client.site, langue: client.langue || 'fr' } }];

const fileId    = $('Convertir HTML en PDF (Google Drive)').first().json.id;
const nom       = $('Préparer HTML Rapport').first().json.nom;
const email     = $('Préparer HTML Rapport').first().json.email;
const site      = $('Préparer HTML Rapport').first().json.site;
const langue    = $('Préparer HTML Rapport').first().json.langue || 'fr';

const pdfLink      = `https://drive.google.com/file/d/${fileId}/view?usp=sharing`;
const downloadLink = `https://drive.google.com/uc?export=download&id=${fileId}`;

return [{ json: { pdfLink, downloadLink, fileId, nom, email, site, langue } }];
